/* ============================================
   CHIP COMPONENT
   Compact pill for attributes, filters, and
   inline metadata. Non-clickable by default;
   clickable, selectable, and removable variants.
   ============================================ */

.ds-chip {
  /* Layout */
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */

  /* Spacing — 32px tall at default size */
  padding: var(--padding-150) var(--padding-300); /* 6px 12px */

  /* Shape */
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-pill);
  background-color: var(--color-bg-page-primary);

  /* Typography — same em style as Badge */
  font-family: var(--font-paragraph-sm-emphasis-family);
  font-size: var(--font-paragraph-sm-emphasis-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-paragraph-sm-emphasis-line-height);
  letter-spacing: var(--font-paragraph-sm-emphasis-letter-spacing);
  color: var(--color-text-secondary);
  white-space: nowrap;

  transition: background-color var(--motion-duration-base) var(--motion-ease-standard), border-color var(--motion-duration-base) var(--motion-ease-standard),
    color var(--motion-duration-base) var(--motion-ease-standard), opacity var(--motion-duration-base) var(--motion-ease-standard);
}

/* ============================================
   SIZE — LARGE (40px tall)
   The default Button's footprint and the body
   paragraph scale, so a chip used as a primary
   tap target reads at the same weight as the
   text around it.
   ============================================ */

.ds-chip--large {
  padding: var(--padding-200) var(--padding-500); /* 8px 20px */
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
}

.ds-chip--large .ds-chip__icon,
.ds-chip--large .ds-chip__remove .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
}

.ds-chip--large .ds-chip__icon svg {
  width: 24px;
  height: 24px;
}

/* ============================================
   SIZE — COMPACT (24px tall)
   ============================================ */

.ds-chip--compact {
  gap: var(--gap-100); /* 4px */
  padding: var(--padding-050) var(--padding-200); /* 2px 8px */
}

/* ============================================
   ICON (leading)
   ============================================ */

.ds-chip__icon {
  flex-shrink: 0;
  --icon-size: var(--icon-size-500);
  line-height: 1;
  color: var(--color-icon-primary);
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-chip__icon svg {
  width: 20px;
  height: 20px;
}

.ds-chip--compact .ds-chip__icon {
  --icon-size: var(--icon-size-500);
}

.ds-chip--compact .ds-chip__icon svg {
  width: 16px;
  height: 16px;
}

/* ============================================
   LABEL
   ============================================ */

.ds-chip__label {
  flex-shrink: 0;
}

/* ============================================
   CLICKABLE (rendered as <button>)
   ============================================ */

.ds-chip--clickable {
  cursor: pointer;
}

.ds-chip--clickable:not(.ds-chip--disabled):not(.ds-chip--selected):hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-chip--clickable:not(.ds-chip--disabled):not(.ds-chip--selected):active {
  background-color: var(--color-action-passive-bg-active);
}

/* ============================================
   SELECTED — teal active fill, matching the
   SegmentedControl selection convention
   ============================================ */

.ds-chip--selected {
  background-color: var(--color-action-primary-bg);
  border-color: var(--color-action-primary-bg);
  color: var(--color-action-primary-text);
}

.ds-chip--selected .ds-chip__icon {
  color: var(--color-action-primary-text);
}

.ds-chip--selected.ds-chip--clickable:not(.ds-chip--disabled):hover {
  background-color: var(--color-action-primary-bg-hover);
}

.ds-chip--selected.ds-chip--clickable:not(.ds-chip--disabled):active {
  background-color: var(--color-action-primary-bg-active);
}

/* ============================================
   REMOVABLE — <span> container with an inner
   main region (when clickable) + close button
   ============================================ */

.ds-chip__main {
  display: inline-flex;
  align-items: center;
  gap: inherit;
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  font: inherit;
  letter-spacing: inherit;
  color: inherit;
  cursor: pointer;
}

.ds-chip__remove {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin: 0;
  padding: 0;
  border: none;
  background: none;
  border-radius: var(--radius-pill);
  color: var(--color-icon-primary);
  cursor: pointer;
  transition: color var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-chip__remove .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
  line-height: 1;
}

.ds-chip--compact .ds-chip__remove .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-chip__remove:not(:disabled):hover {
  color: var(--color-text-primary);
}

.ds-chip--selected .ds-chip__remove {
  color: var(--color-action-primary-text);
}

.ds-chip--selected .ds-chip__remove:not(:disabled):hover {
  color: var(--color-action-primary-text-active);
}

/* ============================================
   DISABLED
   ============================================ */

.ds-chip--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-chip--disabled .ds-chip__main,
.ds-chip--disabled .ds-chip__remove {
  cursor: not-allowed;
}

/* ============================================
   FOCUS
   ============================================ */

.ds-chip--clickable:focus-visible,
.ds-chip__main:focus-visible,
.ds-chip__remove:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-chip .material-symbols-rounded {
  color: inherit;
}

import React from 'react';
import './Chip.css';
import '../../fonts/material-symbols.css';

export interface ChipProps {
  /** Chip label — string for plain text, ReactNode for richer content (e.g. a numbered prefix) */
  label: React.ReactNode;
  /** Leading icon — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Selected state (filter-style chips) — renders the teal active fill */
  selected?: boolean;
  /** Disabled state */
  disabled?: boolean;
  /** Chip size — `large` matches the default Button and paragraph body scale, for pills that are a primary tap target rather than metadata */
  size?: 'large' | 'default' | 'compact';
  /** Click handler — presence makes the chip an interactive <button> */
  onClick?: () => void;
  /** Remove handler — renders a trailing close button (input-style chips) */
  onRemove?: () => void;
  /** Accessible label for the remove button */
  removeLabel?: string;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Chip component — compact pill for attributes, filters, and inline metadata.
 * Non-clickable by default (renders a <span>); pass onClick for an
 * interactive <button>, and/or onRemove for a trailing close button.
 */
export const Chip = ({
  label,
  icon,
  selected,
  disabled = false,
  size = 'default',
  onClick,
  onRemove,
  removeLabel = 'Remove',
  className = '',
}: ChipProps) => {
  const baseClass = 'ds-chip';

  const classes = [
    baseClass,
    `${baseClass}--${size}`,
    selected && `${baseClass}--selected`,
    disabled && `${baseClass}--disabled`,
    onClick && !onRemove && `${baseClass}--clickable`,
    onRemove && `${baseClass}--removable`,
    className,
  ]
    .filter(Boolean)
    .join(' ');

  /** Render the leading icon slot — string → Material Symbol, ReactNode → custom element */
  const renderIcon = (iconProp: string | React.ReactNode) => {
    if (typeof iconProp === 'string') {
      return (
        <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
          {iconProp}
        </span>
      );
    }
    return (
      <span className={`${baseClass}__icon`} aria-hidden="true">
        {iconProp}
      </span>
    );
  };

  const content = (
    <>
      {icon && renderIcon(icon)}
      <span className={`${baseClass}__label`}>{label}</span>
    </>
  );

  // aria-pressed only applies when the chip is an explicit toggle
  const ariaPressed = typeof selected === 'boolean' ? selected : undefined;

  // Removable chip — <span> container so the remove <button> isn't nested
  // inside another button; a clickable main region wraps the content instead
  if (onRemove) {
    return (
      <span className={classes}>
        {onClick ? (
          <button
            type="button"
            className={`${baseClass}__main`}
            onClick={onClick}
            disabled={disabled}
            aria-pressed={ariaPressed}
          >
            {content}
          </button>
        ) : (
          content
        )}
        <button
          type="button"
          className={`${baseClass}__remove`}
          onClick={onRemove}
          disabled={disabled}
          aria-label={removeLabel}
        >
          <span className="material-symbols-rounded" aria-hidden="true">
            close
          </span>
        </button>
      </span>
    );
  }

  if (onClick) {
    return (
      <button
        type="button"
        className={classes}
        onClick={onClick}
        disabled={disabled}
        aria-pressed={ariaPressed}
      >
        {content}
      </button>
    );
  }

  return <span className={classes}>{content}</span>;
};
